import{_ as t,l as r,o as a,c as i,v as o,p as l,x as s,d as p,i as h,S as E}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"Jones 矩阵","description":"","frontmatter":{"title":"Jones 矩阵","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/jones-polarization.md","filePath":"litho/jones-polarization.md","lastUpdated":1789023840000}'),m={name:"litho/jones-polarization.md"};function d(c,e,A,_,J,f){const n=r("Mermaid");return a(),i("div",null,[e[1]||(e[1]=o('<h1 id="jones-矩阵" tabindex="-1">Jones 矩阵 <a class="header-anchor" href="#jones-矩阵" aria-label="Permalink to &quot;Jones 矩阵&quot;">​</a></h1><div class="epigraph"><p>TE / TM 已经给出两条通道的对比差；要把偏振器、波片和局部 s/p 旋转串成一条光线，需要 $2\\times 2$ 的 Jones 演算，而不是再比一次点积。</p><footer>—— R. C. Jones 的偏振矩阵演算；教材表述见 Born &amp; Wolf, Principles of Optics</footer></div><p><a href="/litho/te-tm-polarization">上一课</a>把密线对比差钉在电矢量平行还是躺在入射面里。缺口是：<strong>通道之间如何沿光路相乘</strong>。点积损失是像面结局；Jones 矩阵是途中的算法。光瞳相位如何展开，留给<a href="/litho/zernike-aberrations">Zernike 像差</a>。不要从瑞利 CD 起笔，也不要引用未公开的机台偏振纯度指标。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>上一课选定了「好偏振」与「坏偏振」，却没有把一块起偏器、一层延迟、一次坐标转到局部 s/p 写成可级联的算符。高 \\(\\mathrm{NA}\\) 每条光线的 s/p 基底随方位角转，实验室 \\(x/y\\) 不是全局的 TE/TM。缺口因此是偏振的<strong>矩阵语言</strong>，而不是再解释为何标量不够。</p><p>完全偏振、单色时，场用 Jones 矢量 \\((E_x,E_y)^\\mathrm{T}\\)。每个光学元件（或沿光线的一小段）是 \\(2\\times 2\\) 复矩阵，系统总矩阵是沿传播顺序的乘积。部分偏振要改 Stokes / Mueller，后课计量会用；成像主干先用 Jones。</p><h3 id="jones-不是又一种对比定义" tabindex="-1">Jones 不是又一种对比定义 <a class="header-anchor" href="#jones-不是又一种对比定义" aria-label="Permalink to &quot;Jones 不是又一种对比定义&quot;">​</a></h3><p>NILS 的输入仍是能量沉积。Jones 只负责在到达薄膜之前把矢量分量算对。把「Jones 矩阵对角」直接叫成高对比，会跳过像面点积与胶内 Fresnel——那两步仍属于上一课与矢量成像课。</p><p><span class="marginnote">Jones 假定完全偏振、单色、无退偏。镀膜散射、多层膜粗糙会把能量打进非偏振通道，必须改 Mueller；本课不把退偏写进 \\(2\\times 2\\)。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>约定基底（实验室 \\(x/y\\)，或随光线的 s/p）。线起偏器、四分之一波片、旋转矩阵 \\(R(\\psi)\\) 都有标准 Jones 表，见 Jones 原文与 Born &amp; Wolf。光线从照明进入投影后：先把全局 Jones 旋到该光线的 s/p，乘镀膜的对角（s、p 振幅透过率不同），再旋回像面基底，与其他衍射级叠加。Flagello / Yeung 的矢量核正是把这一串藏进传递；本课把藏着的 \\(2\\times 2\\) 写明。</p><p>照明侧切向偏振，等于在源瞳每个方位放一个随 \\(\\phi\\) 转的线起偏器——仍是 Jones，只是源点相关。它不改 \\(\\mathrm{NA}/\\lambda\\) 截止。</p><h3 id="级联顺序不能交换" tabindex="-1">级联顺序不能交换 <a class="header-anchor" href="#级联顺序不能交换" aria-label="Permalink to &quot;级联顺序不能交换&quot;">​</a></h3><p>偏振器与波片一般不对易。光瞳边缘的 s/p 旋转角最大，同样的镀膜相位差在边缘比在中心更伤 TM 通道。这把「偏振税随 \\(\\mathrm{NA}\\) 涨」从点积语言接到矩阵语言：旋转角进 \\(R\\)，镀膜进对角元，两者相乘。</p><p><span class="marginnote">掩模吸收体也可以有 Jones（取向相关透过率）。薄屏标量 \\(t\\) 没有这张矩阵；厚掩模电磁课才会把它算出来。本课的物默认已经是进光瞳的 Jones 矢量。</span></p>',15)),(a(),l(E,null,{default:s(()=>[h(n,{id:"mermaid-43",class:"mermaid",graph:"flowchart%20TD%0A%20%20TM%5B%22%E4%B8%8A%E4%B8%80%E8%AF%BE%EF%BC%9ATE%2FTM%20%E5%AF%B9%E6%AF%94%22%5D%20--%3E%20J%5B%22Jones%20%E7%9F%A2%E9%87%8F%22%5D%0A%20%20J%20--%3E%20M%5B%222%C3%972%20%E5%85%83%E4%BB%B6%E7%9F%A9%E9%98%B5%22%5D%0A%20%20M%20--%3E%20R%5B%22%E6%97%8B%E5%88%B0%E5%B1%80%E9%83%A8%20s%2Fp%22%5D%0A%20%20R%20--%3E%20COAT%5B%22%E9%95%80%E8%86%9C%E5%AF%B9%E8%A7%92%22%5D%0A%20%20COAT%20--%3E%20IMG%5B%22%E5%83%8F%E9%9D%A2%E7%9F%A2%E9%87%8F%E5%8F%A0%E5%8A%A0%22%5D%0A%20%20IMG%20--%3E%20NEXT%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E5%85%89%E7%9E%B3%E7%9B%B8%E4%BD%8D%20W%22%5D%0A"})]),fallback:s(()=>[...e[0]||(e[0]=[p(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=o('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>两束光在像面的交叉项是 \\(\\mathbf{E}_1\\cdot\\mathbf{E}_2^*\\)。Jones 把每个 \\(\\mathbf{E}\\) 从源追到像：若系统矩阵把本该平行的 TE 分量拧出 TM 分量，点积在到达之前就已经被稀释。机制仍是上一课的夹角，计算单元换成矩阵。非偏振照明是两正交 Jones 矢量各算一遍再加强度，得到中间对比——与上一课「非偏振是平均」一致。</p><p>几何像差（下一课的 \\(W\\)）在标量里是公共相位 \\(e^{ikW}\\)，乘在 Jones 矢量上等于乘单位矩阵的相位因子；各向异性镀膜才会让两偏振看见不同的 \\(W\\)。先把公共相位放进 Zernike，再问镀膜双折射。</p><h3 id="后课默认的接口" tabindex="-1">后课默认的接口 <a class="header-anchor" href="#后课默认的接口" aria-label="Permalink to &quot;后课默认的接口&quot;">​</a></h3><p>说到偏振传递，默认可以用 Jones 级联（完全偏振）或声明改用 Mueller（退偏）。Zernike 相位默认乘在两个通道上，与本课矩阵相乘，不互相替代。截止频率仍是 \\(\\mathrm{NA}/\\lambda\\)。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不是掩模 FDTD，不是 EUV 多层膜反射率光谱。不要把 Jones 写成已经包含部分相干：每个源点一张 Jones，强度事后相加。禁止引用未公开的偏振消光比验收表；Jones 的代数与 Born &amp; Wolf 的表述已经够用。</p><p>椭圆偏振、延迟量随波长变，是色差课与膜系课的交叉，此处单色。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>TE/TM 对比是结局；Jones 是沿光线的 \\(2\\times 2\\) 演算。</li><li>高 \\(\\mathrm{NA}\\) 必须旋到局部 s/p 再乘镀膜，顺序不能随便交换。</li><li>完全偏振用 Jones；退偏改 Mueller。</li><li>公共几何相位下一课用 Zernike 展开，与本课矩阵相乘。</li><li>本课不改 NILS 定义，只改进入 \\(I\\) 的矢量。</li><li>出处：Jones, JOSA 偏振演算论文；Born &amp; Wolf, <em>Principles of Optics</em>。</li></ul>',10))])}const T=t(m,[["render",d]]);export{B as __pageData,T as default};
